package mjml

import (
	"bufio"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// TestLayerSweepParity compares every document of the layer sweep with its
// MJML 5.4.1 reference: each attribute of each body component, set in one or
// several layers (element, mj-class, the mj-attributes tag, mj-all, the
// parent and the grandparent), with values and empty values. The sweep is
// generated by tools/mjml-reference/layer-sweep.mjs into SAFE_MJML_SWEEP_DIR (the
// CI does it); without it the test is skipped.
//
// The documents that still differ are listed in
// testdata/sweep-known-failures.txt ("name: reason"). Any other difference
// fails, and so does a listed document that matches MJML, so that the list
// cannot go stale.
func TestLayerSweepParity(t *testing.T) {
	dir := os.Getenv("SAFE_MJML_SWEEP_DIR")
	if dir == "" {
		t.Skip("set SAFE_MJML_SWEEP_DIR to a directory written by tools/mjml-reference/layer-sweep.mjs")
	}
	checkDirectoryParity(t, dir, "sweep-known-failures.txt")
}

// TestOfficialTemplates compares MJML's 25 official email templates
// (github.com/mjmlio/email-templates, written with their MJML 5.4.1
// references by tools/mjml-reference/official.mjs into SAFE_MJML_OFFICIAL_DIR,
// as the CI does) with their references. The templates that still differ are
// listed in testdata/official-known-failures.txt ("name: reason").
func TestOfficialTemplates(t *testing.T) {
	dir := os.Getenv("SAFE_MJML_OFFICIAL_DIR")
	if dir == "" {
		t.Skip("set SAFE_MJML_OFFICIAL_DIR to a directory written by tools/mjml-reference/official.mjs")
	}
	checkDirectoryParity(t, dir, "official-known-failures.txt")
}

// checkDirectoryParity renders every document of dir with the carousel and
// navbar IDs of its MJML reference, and fails on one that safe-mjml cannot
// render or that differs from MJML, unless the testdata file list names it
// with its reason; a listed document that matches MJML, or that dir does
// not hold, fails too, so that the list cannot go stale.
func checkDirectoryParity(t *testing.T, dir, list string) {
	t.Helper()
	files, err := filepath.Glob(filepath.Join(dir, "*.mjml"))
	if err != nil || len(files) == 0 {
		t.Fatalf("no document in %s: %v", dir, err)
	}
	sort.Strings(files)
	known := readKnownFailuresFile(t, list)
	present := map[string]bool{}
	for _, file := range files {
		name := strings.TrimSuffix(filepath.Base(file), ".mjml")
		present[name] = true
		reference, err := os.ReadFile(strings.TrimSuffix(file, ".mjml") + ".html")
		if err != nil {
			continue // MJML rejected the document
		}
		source, err := os.ReadFile(file)
		if err != nil {
			t.Fatal(err)
		}
		html, renderErr := Render(string(source), WithIDGenerator(referenceIDGenerator(string(reference))))
		matches := renderErr == nil && len(referenceDifferences(string(reference), html)) == 0
		_, isKnown := known[name]
		switch {
		case isKnown && matches:
			t.Errorf("%s now matches MJML: remove it from testdata/%s", name, list)
		case !isKnown && renderErr != nil:
			t.Errorf("%s: Render: %v", name, renderErr)
		case !isKnown && !matches:
			t.Errorf("%s differs from MJML 5.4.1 (%s):\n%s", name, file, strings.Join(referenceDifferences(string(reference), html), "\n"))
		}
	}
	for name := range known {
		if !present[name] {
			t.Errorf("%s lists %s, which %s does not hold", list, name, dir)
		}
	}
}

// readKnownFailuresFile reads a list of testdata ("name: reason" lines, # for
// comments): the documents that differ from MJML, with the reason.
func readKnownFailuresFile(t *testing.T, list string) map[string]string {
	t.Helper()
	known := map[string]string{}
	file, err := os.Open(filepath.Join("testdata", list))
	if os.IsNotExist(err) {
		return known
	}
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		name, reason, ok := strings.Cut(line, ":")
		if !ok || strings.TrimSpace(reason) == "" {
			t.Fatalf("%s: %q is not \"name: reason\"", list, line)
		}
		known[strings.TrimSpace(name)] = strings.TrimSpace(reason)
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	return known
}
